def pin_saved_values(apps, schema_editor):
    """Every number a person saved on configMaxxing before auto-tuning existed is pinned: the tuner never moves a setting with a saved value.
    Nothing is copied: the saved value itself is the pin. This only records who saved it where the row did not say (an older save kept the
    row's last saver only), so the page can say "Pinned by <user>"."""
    for name in ('ScanConcurrency', 'TunableSettings'):
        Model = apps.get_model('cveFeed', name)
        for row in Model.objects.all():
            meta = dict(row.meta or {})
            saver = row.updated_by.username if row.updated_by_id else ''
            changed = False
            for key in (row.values or {}):
                entry = dict(meta.get(key) or {})
                if not entry.get('by'):
                    entry['by'] = saver or 'an administrator'
                    meta[key] = entry
                    changed = True
            if changed:
                Model.objects.filter(pk=row.pk).update(meta=meta)


def schedule(apps, schema_editor):
    Interval = apps.get_model('django_celery_beat', 'IntervalSchedule')
    PeriodicTask = apps.get_model('django_celery_beat', 'PeriodicTask')
    interval, _ = Interval.objects.get_or_create(every=10, period='minutes')
    PeriodicTask.objects.get_or_create(name='cvengine-autotune', defaults={
        'task': 'autotune', 'interval': interval, 'enabled': True, 'queue': 'cve_feed_queue'})


def unschedule(apps, schema_editor):
    apps.get_model('django_celery_beat', 'PeriodicTask').objects.filter(name='cvengine-autotune').delete()


